#include <bits/stdc++.h>
#define err(args...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using ll = long long;
const int N = 10;
string g[N];
int n_scientists[N][N] = {};
int n_rescue[N][N] = {};
int infect_time[N][N] = {};
int di[] = {-1, 1, 0, 0};
int dj[] = {0, 0, -1, 1};
int reach_time[N][N][N][N] = {};
const int FLOW_N = 2 * N * N + 2;
const int INF = 1'000'000'000;
vector<int> adj[FLOW_N+1];
int c[FLOW_N+1][FLOW_N+1], f[FLOW_N+1][FLOW_N+1], adj_ptr[FLOW_N+1], d[FLOW_N+1], p[FLOW_N+1];
bool make_level_graph(int s, int t) {
    memset(d, -1, sizeof d);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    while(not q.empty()) {
        int u = q.front();
        q.pop();
        for(int v : adj[u]) {
            if(c[u][v] - f[u][v] > 0 and d[v] == -1) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }
    return d[t] != -1;
}
bool dfs(int u, int t) {
    if(u == t) return true;
    for(int& i = adj_ptr[u]; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(d[v] == d[u] + 1 and c[u][v] - f[u][v] > 0 and dfs(v, t)) {
            p[v] = u;
            return true;
        }
    }
    return false;
}
bool find_aug_path(int s, int t) {
    memset(p, -1, sizeof p);
    p[s] = 0;
    return dfs(s, t);
}
void init_flow() {
    memset(c, 0, sizeof c);
    memset(f, 0, sizeof f);
}
void add_edge(int u, int v, int capacity) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    c[u][v] += capacity;
}
int max_flow(int s, int t) {
    int max_flow_value = 0;
    while(make_level_graph(s, t)) {
        memset(adj_ptr, 0, sizeof adj_ptr);
        while(find_aug_path(s, t)) {
            int b = INF;
            for(int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                b = min(b, c[u][v] - f[u][v]);
            }
            for(int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                f[u][v] += b;
                f[v][u] -= b;
            }
            max_flow_value += b;
        }
    }
    return max_flow_value;
}
int node(int n, int i, int j, bool right) {
    return i * n + j + (right ? n * n : 0);
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, t;
    cin >> n >> t;
    string line;
    pair<int, int> explode;
    for(int i = 0; i < n; i++) {
        cin >> line;
        for(int j = 0; j < n; j++) {
            if(line[j] == 'Y') {
                g[i][j] = 'Y';
            } else if(line[j] == 'Z') {
                g[i][j] = 'Z';
                explode = {i, j};
            } else {
                g[i][j] = '.';
                n_scientists[i][j] += line[j] - '0';
            }
        }
    }
    for(int i = 0; i < n; i++) {
        cin >> line;
        for(int j = 0; j < n; j++) {
            if(line[j] != 'Y' and line[j] != 'Z') {
                n_rescue[i][j] += line[j] - '0';
            }
        }
    }
    memset(infect_time, -1, sizeof infect_time);
    infect_time[explode.first][explode.second] = 0;
    queue<pair<int, int>> q;
    q.push(explode);
    while(not q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for(int d = 0; d < 4; d++) {
            int ni = i + di[d], nj = j + dj[d];
            if(0 <= ni and ni < n and 0 <= nj and nj < n and g[ni][nj] == '.' and infect_time[ni][nj] == -1) {
                infect_time[ni][nj] = infect_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
    memset(reach_time, -1, sizeof reach_time);
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(g[i][j] == '.') {
                reach_time[i][j][i][j] = 0;
                queue<pair<int, int>> q;
                q.push({i, j});
                while(not q.empty()) {
                    int ii = q.front().first, jj = q.front().second;
                    q.pop();
                    if(infect_time[ii][jj] == -1 or reach_time[i][j][ii][jj] < infect_time[ii][jj]) {
                        for(int d = 0; d < 4; d++) {
                            int ni = ii + di[d], nj = jj + dj[d];
                            if(0 <= ni and ni < n and 0 <= nj and nj < n and g[ni][nj] == '.'
                            and (infect_time[ni][nj] == -1 or reach_time[i][j][ii][jj] + 1 <= infect_time[ni][nj])
                            and reach_time[i][j][ni][nj] == -1) {
                                reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                q.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }
    }
    int src = 2 * n * n, sink = 2 * n * n + 1;
    init_flow();
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(n_scientists[i][j]) {
                add_edge(src, node(n, i, j, false), n_scientists[i][j]);
            }
            if(n_rescue[i][j]) {
                add_edge(node(n, i, j, true), sink, n_rescue[i][j]);
            }
            for(int ii = 0; ii < n; ii++) {
                for(int jj = 0; jj < n; jj++) {
                    if(0 <= reach_time[i][j][ii][jj] and reach_time[i][j][ii][jj] <= t) {
                        add_edge(node(n, i, j, false), node(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }
    cout << max_flow(src, sink) << endl;
    return 0;
}

